<template>
 <section class="fee-policies">
  <header><div><h2>{{platform?'Platform attendance fee defaults':'Attendance fees and cancellation policies'}}</h2><p>Review the normal customer session price alongside the late-cancellation and no-show fees. Employee wages are separate.</p></div><button type="button" @click="start">Add {{platform?'platform default':'policy'}}</button></header>
  <router-link v-if="!platform && auth.user?.role==='super_admin'" to="/admin/attendance-fees">Manage platform fee defaults</router-link>
  <p>Appointment terms and purchased package terms take precedence. Organization rules override platform defaults. A saved change creates a new version; existing appointments retain their original policy.</p>
  <p v-if="error" role="alert">{{error}}</p><p v-if="notice" role="status">{{notice}}</p><p v-if="loading" role="status">Loading fee policies…</p>
  <form v-if="editing" @submit.prevent="save">
   <label>Policy name<input v-model="draft.name" required maxlength="200" /></label>
   <label v-if="!platform">Scope<select v-model="draft.scopeLevel"><option value="tenant">Organization default</option><option value="business_type">Service type</option><option value="payer">Payer / funding type</option><option value="service">Specific service</option><option value="rate_category">Category / customer tier</option><option value="package">Package</option></select></label>
   <div class="grid"><label>Service type<select v-model="draft.businessType"><option :value="null">Any service type</option><option value="tutoring">Tutoring</option><option value="learning">Learning</option><option value="mental_health">Counseling</option><option value="healthcare">Healthcare</option></select></label><label>Payer / funding type<select v-model="draft.payerType"><option :value="null">Any funding type</option><option value="self_pay">Self-pay</option><option value="insurance">Insurance</option><option value="medicaid">Medicaid</option><option value="commercial">Commercial insurance</option><option value="medicare">Medicare</option></select></label></div>
   <label v-if="!platform && draft.scopeLevel==='service'">Specific service<select v-model="draft.tenantServiceId" required><option :value="null">Choose a service</option><option v-for="service in referenceServices" :key="service.id" :value="Number(service.id)">{{service.name}}</option></select></label>
   <label>Service code<select v-model="draft.serviceCode"><option :value="null">Any service code</option><option v-for="code in serviceCodes" :key="code" :value="code">{{code}}</option></select></label>
   <label v-if="draft.scopeLevel==='package'">Package<select v-model="draft.bookingPackageId" required><option :value="null">Choose a package</option><option v-for="pkg in packages" :key="pkg.id" :value="Number(pkg.id)">{{pkg.name}}</option></select></label>
   <div class="grid"><label>NLU employee category (placement only)<select v-model="draft.providerCategory"><option :value="null">Any category</option><option v-for="n in 4" :key="n" :value="n">Category {{n}}</option></select></label><label>NLU employee level (placement only)<select v-model="draft.providerLevel"><option :value="null">Any level</option><option v-for="n in 5" :key="n" :value="n">Level {{n}}</option></select></label><label>Tutoring customer pricing tier<select v-model="draft.customerTierId"><option :value="null">Any customer tier</option><option v-for="n in 5" :key="n" :value="`L${n}`">L{{n}}</option></select></label><label>Format<select v-model="draft.modality"><option :value="null">Both formats</option><option value="TELEHEALTH">Virtual</option><option value="IN_PERSON">In person</option></select></label></div>
   <section class="price-comparison"><h3>Normal customer price for comparison</h3><p>This comparison does not change the provider’s service price or restrict the rule to this one person.</p><label v-if="referenceAgencyId">Provider<select v-model="referenceProviderId" @change="loadReference"><option :value="null">Organization catalog rate</option><option v-for="person in providers" :key="person.id" :value="Number(person.id)">{{person.name}}</option></select></label><p v-else>Choose an organization in the workspace to compare its customer prices.</p><p v-if="referenceLoading" role="status">Loading customer prices…</p><p v-if="referenceError" role="alert">{{referenceError}} <button type="button" @click="loadReference">Retry</button></p>
    <div class="table-wrap"><table v-if="visibleReferences.length"><thead><tr><th>Service / format</th><th>Normal session price</th><th>Late-cancellation fee</th><th>No-show fee</th></tr></thead><tbody><template v-for="service in visibleReferences" :key="service.serviceId"><tr v-for="(quote,format) in service.quotes" :key="format"><td>{{service.name}} · {{format==='IN_PERSON'?'In person':'Virtual'}} · {{service.durationMinutes}} min</td><td>{{money(quote.amountCents)}}</td><td>{{money(cents(draft.lateDollars))}}</td><td>{{money(cents(draft.noShowDollars))}}</td></tr></template></tbody></table></div><p v-if="placement">Reference placement: category {{placement.providerCategory||'not available'}}, level {{placement.providerLevel||'not available'}} · Customer tier {{placement.customerTierId||'not available'}}.</p>
   </section>
   <div class="grid"><label>Cancellation notice (hours)<input v-model.number="draft.noticeHours" type="number" min="0" max="8760" step="1" required /></label><label>Late-cancellation fee ($)<input v-model="draft.lateDollars" type="number" min="0" step="0.01" required /></label><label>No-show fee ($)<input v-model="draft.noShowDollars" type="number" min="0" step="0.01" required /></label></div>
   <div class="grid"><label>Suggested arrival wait (minutes)<input v-model.number="draft.noShowSuggestedWaitMinutes" type="number" min="0" max="120" step="1" required /></label><label>Undo / notice delay after scheduled end (minutes)<input v-model.number="draft.noShowUndoAfterEndMinutes" type="number" min="0" max="1440" step="1" required /></label></div>
   <label>Late package action<select v-model="draft.latePackageAction"><option value="forfeit">Apply the package’s missed-session policy</option><option value="release">Retain the session credit</option><option value="review">Office review required</option></select></label>
   <p>Recording a no-show during the first {{draft.noShowSuggestedWaitMinutes}} minutes asks for confirmation. It can be undone until {{draft.noShowUndoAfterEndMinutes}} minutes after the scheduled end. The client notice and provider copy become due then. Payer restrictions and signed package allowances still apply.</p>
   <label class="check"><input v-model="draft.isActive" type="checkbox" /> Active for new matching appointments</label><div class="actions"><button type="submit" :disabled="busy">{{busy?'Saving…':draft.id?'Save new policy version':'Save policy'}}</button><button type="button" :disabled="busy" @click="editing=false">Cancel</button></div>
  </form>
  <div class="table-wrap"><table v-if="policies.length"><thead><tr><th>Policy / scope</th><th>Notice</th><th>Late cancellation</th><th>No-show</th><th></th></tr></thead><tbody><tr v-for="policy in policies" :key="policy.id"><td>{{policy.name}} · {{policy.scopeLevel}}<small>{{filters(policy)}}</small><small v-if="!policy.isActive">Inactive / previous version</small></td><td>{{policy.noticeHours}} hours</td><td>{{money(policy.lateFeeCents)}}</td><td>{{money(policy.noShowFeeCents)}}</td><td><button v-if="policy.isActive" type="button" @click="start(policy)">Review / change</button></td></tr></tbody></table></div>
  <p v-if="!loading&&!policies.length">No {{platform?'platform defaults':'organization policies'}} configured.</p><details v-if="platformDefaults.length"><summary>Inherited platform defaults</summary><p v-for="policy in platformDefaults" :key="policy.id">{{policy.name}} · {{filters(policy)}} · {{policy.noticeHours}} hours · Late {{money(policy.lateFeeCents)}} · No-show {{money(policy.noShowFeeCents)}}</p><p>An organization override takes precedence over these defaults.</p></details>
 </section>
</template>
<script setup>
import {computed,ref,watch} from 'vue';
import api from '../../services/api';
import {useAgencyStore} from '../../store/agency';
import {useAuthStore} from '../../store/auth';
const props=defineProps({agencyId:[Number,String],platform:Boolean,referenceServices:{type:Array,default:()=>[]},packages:{type:Array,default:()=>[]}});
const agency=useAgencyStore(),auth=useAuthStore();
const policies=ref([]),platformDefaults=ref([]),editing=ref(false),busy=ref(false),loading=ref(false),error=ref(''),notice=ref(''),draft=ref({});
const providers=ref([]),references=ref([]),placement=ref(null),referenceProviderId=ref(null),referenceLoading=ref(false),referenceError=ref('');let version=0,referenceVersion=0;
const scope=computed(()=>props.platform?'platform':Number(props.agencyId)),referenceAgencyId=computed(()=>Number(props.agencyId||agency.currentAgency?.id)||null);
const serviceCodes=computed(()=>[...new Set(['TUTORING','HOMEWORK_HELP',...props.referenceServices.map(service=>service.serviceCode),...references.value.map(service=>service.serviceCode).filter(Boolean)])]);
const visibleReferences=computed(()=>references.value.filter(service=>(!draft.value.tenantServiceId||Number(service.serviceId)===Number(draft.value.tenantServiceId))&&(!draft.value.businessType||service.businessType===draft.value.businessType)&&(!draft.value.serviceCode||service.serviceCode===draft.value.serviceCode)));
const cents=value=>/^\d+(?:\.\d{1,2})?$/.test(String(value))?Math.round(Number(value)*100):null;
const money=value=>value==null?'Not configured':new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(Number(value)/100);
const filters=policy=>[policy.businessType,policy.serviceCode,policy.payerType,policy.providerCategory?`NLU category ${policy.providerCategory}`:null,policy.providerLevel?`Level ${policy.providerLevel}`:null,policy.customerTierId,policy.modality==='IN_PERSON'?'In person':policy.modality==='TELEHEALTH'?'Virtual':null].filter(Boolean).join(' · ')||'All matching services';
function start(policy=null){draft.value={id:policy?.id||null,name:policy?.name||'',scopeLevel:props.platform?'platform':policy?.scopeLevel||'tenant',businessType:policy?.businessType||null,payerType:policy?.payerType||null,serviceCode:policy?.serviceCode||null,tenantServiceId:policy?.tenantServiceId||null,bookingPackageId:policy?.bookingPackageId||null,providerCategory:policy?.providerCategory||null,providerLevel:policy?.providerLevel||null,customerTierId:policy?.customerTierId||null,modality:policy?.modality||null,allowClientCancel:policy?.allowClientCancel??true,requireReason:policy?.requireReason??true,complimentaryCancelsPerPeriod:policy?.complimentaryCancelsPerPeriod??0,periodDays:policy?.periodDays??90,noShowSuggestedWaitMinutes:policy?.noShowSuggestedWaitMinutes??15,noShowUndoAfterEndMinutes:policy?.noShowUndoAfterEndMinutes??10,noticeHours:policy?.noticeHours??24,lateDollars:((policy?.lateFeeCents||0)/100).toFixed(2),noShowDollars:((policy?.noShowFeeCents??policy?.lateFeeCents??0)/100).toFixed(2),latePackageAction:policy?.latePackageAction||'forfeit',isActive:policy?.isActive??true};editing.value=true;notice.value='';loadReference();}
async function load(){const own=++version;policies.value=[];platformDefaults.value=[];editing.value=false;error.value='';if(!scope.value)return;loading.value=true;try{const {data}=await api.get(`/tenant-booking/agencies/${scope.value}/cancellation-policies`,{params:{includeInactive:true},skipGlobalLoading:true});if(own!==version)return;policies.value=data.policies||[];platformDefaults.value=data.platformDefaults||[];}catch(e){if(own===version)error.value=e.response?.data?.error?.message||'Fee policies could not be loaded.';}finally{if(own===version)loading.value=false;}}
async function loadReference(){const own=++referenceVersion;references.value=[];placement.value=null;referenceError.value='';if(!referenceAgencyId.value)return;referenceLoading.value=true;try{const {data}=await api.get(`/tenant-booking/agencies/${referenceAgencyId.value}/cancellation-price-reference`,{params:{providerId:referenceProviderId.value||undefined},skipGlobalLoading:true});if(own!==referenceVersion)return;providers.value=data.providers||[];references.value=data.references||[];placement.value=data.placement;}catch(e){if(own===referenceVersion)referenceError.value=e.response?.data?.error?.message||'The normal customer price could not be loaded.';}finally{if(own===referenceVersion)referenceLoading.value=false;}}
async function save(){if(busy.value)return;error.value='';const lateFeeCents=cents(draft.value.lateDollars),noShowFeeCents=cents(draft.value.noShowDollars);if(lateFeeCents==null||noShowFeeCents==null){error.value='Enter fees of zero or more with at most two decimal places.';return;}busy.value=true;try{const body={...draft.value,lateFeeCents,noShowFeeCents};const path=`/tenant-booking/agencies/${scope.value}/cancellation-policies`;await(draft.value.id?api.patch(`${path}/${draft.value.id}`,body):api.post(path,body));await load();notice.value='Policy saved. Existing booked terms are preserved.';}catch(e){error.value=e.response?.data?.error?.message||'The fee policy could not be saved.';}finally{busy.value=false;}}
watch(scope,load,{immediate:true});
</script>
<style scoped>.fee-policies,.fee-policies form,.grid,.grid>label,.price-comparison,.table-wrap{min-width:0;max-width:100%;box-sizing:border-box}.fee-policies form>label{min-width:0}.fee-policies input,.fee-policies select{max-width:100%}.fee-policies{line-height:1.5}.fee-policies header,.actions{display:flex;gap:16px;justify-content:space-between;align-items:flex-start}.fee-policies h2{font-size:1.25rem;margin:0}.fee-policies form{display:grid;gap:16px;margin:16px 0;padding:20px;background:var(--bg-primary,#fff);border:1px solid #ceddd7;border-radius:12px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.fee-policies label{display:grid;gap:6px}.fee-policies input,.fee-policies select{min-height:44px;font:inherit;padding:8px;box-sizing:border-box;width:100%}.check{display:flex!important;align-items:center}.check input{width:auto}.table-wrap{overflow:auto}table{border-collapse:collapse;width:100%;font-size:.9rem}th,td{text-align:left;border-bottom:1px solid #d6e1dc;padding:12px}small{display:block}button{min-height:40px;padding:8px 12px}.price-comparison{padding:16px;background:#f1f7f4;border-radius:10px}@media(max-width:700px){.grid{grid-template-columns:1fr}header{flex-wrap:wrap}form{padding:14px!important}}[role=alert]{color:#8e2222}</style>
